import sys
sys.path.insert(0,'/tmp')
from probe import run_capture
def grid_from_raw(raw, rows=24, cols=80):
    txt = raw.decode(errors='replace')
    grid = [[' ']*cols for _ in range(rows)]
    cur_r, cur_c = 0,0
    i=0
    n=len(txt)
    while i<n:
        if txt[i]=='\x1b' and i+1<n and txt[i+1]=='[':
            j=i+2
            while j<n and (txt[j].isdigit() or txt[j] in ';?:'):
                j+=1
            if j>=n:
                break
            cmd=txt[j]
            params=txt[i+2:j]
            if cmd=='H':
                if ';' in params:
                    r,c = params.split(';')
                    cur_r=int(r)-1
                    cur_c=int(c)-1
                elif params=='':
                    cur_r,cur_c=0,0
            elif cmd=='J':
                if params=='2':
                    grid=[[' ']*cols for _ in range(rows)]
                    cur_r,cur_c=0,0
            i=j+1
        elif txt[i]=='\x1b' and i+1<n and txt[i+1]=='(':
            i+=3
        else:
            ch=txt[i]
            if ch=='\n':
                cur_r+=1
                cur_c=0
            elif ch=='\r':
                cur_c=0
            else:
                if 0<=cur_r<rows and 0<=cur_c<cols:
                    grid[cur_r][cur_c]=ch
                    cur_c+=1
                    if cur_c>=cols:
                        cur_c=0
                        cur_r+=1
            i+=1
    return [''.join(row) for row in grid]

def show_grid(grid):
    for idx, line in enumerate(grid, start=1):
        print(f"{idx:2d}|{line}|")

import tempfile, os

def test_keys(content, keys, desc, args=[], rows=24, cols=80):
    print(f"\n===== {desc} keys={keys!r} =====")
    tf=tempfile.NamedTemporaryFile(mode='wb', delete=False, suffix='.txt')
    tf.write(content); tf.close()
    fname=tf.name
    out=run_capture(args+[fname], keys=keys, rows=rows, cols=cols)
    os.unlink(fname)
    grid=grid_from_raw(out, rows=rows, cols=cols)
    show_grid(grid)
    return out

# Need to understand cursor: initial selected is "all". Moving with l/h/j/k?
