// ===== App =====
struct App {
    root: Node,
    total: u64,
    display_name: String,
    debug: bool,
    // navigation
    levels: Vec<Vec<BlockInfo>>,
    zoom_path: Option<Vec<String>>,
    zoom_total: u64,
    sel_depth: usize,
    sel_idx: usize,
    scroll: usize,
    // search
    query: Option<String>,
    query_re: Option<regex::Regex>,
    matches: Vec<(usize, usize)>,
    match_idx: Option<usize>,
    // input mode
    input_mode: bool,
    input_text: String,
    input_cursor: usize,
    // info (invalid regex)
    info_msg: Option<String>,
    // timings for debug
    build_time: Duration,
}
impl App {
    fn new(root: Node, total: u64, display_name: String, debug: bool, cols: usize) -> Self {
        let t0 = Instant::now();
        let levels = collect_levels(&root, &None, total, cols);
        let build_time = t0.elapsed();
        App { root, total, display_name, debug, levels, zoom_path: None, zoom_total: total, sel_depth: 0, sel_idx: 0, scroll: 0, query: None, query_re: None, matches: vec![], match_idx: None, input_mode: false, input_text: String::new(), input_cursor: 0, info_msg: None, build_time }
    }
    fn rebuild(&mut self, cols: usize) {
        let t0 = Instant::now();
        let zt = if let Some(p) = &self.zoom_path {
            // find zoom total
            let mut cur = &self.root;
            let mut tot = self.root.total;
            for name in p {
                if let Some(c) = cur.children.iter().find(|c| &c.name == name) { tot = c.total; cur = c; } else { break; }
            }
            tot
        } else { self.total };
        self.zoom_total = zt;
        self.levels = collect_levels(&self.root, &self.zoom_path, self.total, cols);
        // Note: total_for_width param is self.total, but zoom_total used inside? Actually collect_levels uses zoom_total internally for widths, but we pass self.total as total_for_width (unused when zoomed? It uses zoom_total for widths). Good.
        self.build_time = t0.elapsed();
        // clamp selection
        self.clamp_sel();
        self.update_matches();
    }
    fn clamp_sel(&mut self) {
        if self.levels.is_empty() { self.sel_depth=0; self.sel_idx=0; self.scroll=0; return; }
        if self.sel_depth >= self.levels.len() { self.sel_depth = self.levels.len()-1; }
        let lvl_len = self.levels[self.sel_depth].len();
        if lvl_len==0 { self.sel_idx=0; } else if self.sel_idx >= lvl_len { self.sel_idx = lvl_len-1; }
    }
    fn selected_block(&self) -> Option<&BlockInfo> {
        self.levels.get(self.sel_depth)?.get(self.sel_idx)
    }
    fn update_matches(&mut self) {
        self.matches.clear();
        self.match_idx = None;
        if let Some(re) = &self.query_re {
            for (d, lvl) in self.levels.iter().enumerate() {
                if d==0 { continue; } // skip all
                for (i, b) in lvl.iter().enumerate() {
                    if re.is_match(&b.name) {
                        self.matches.push((d,i));
                    }
                }
            }
            // match_idx stays None until n pressed? Actually after search, selected stays, match_idx None. n will go to first.
        }
    }
    fn match_total(&self) -> u64 {
        if self.query_re.is_none() { return 0; }
        let mut sum = 0;
        for (d,i) in &self.matches {
            if let Some(lvl) = self.levels.get(*d) {
                if let Some(b) = lvl.get(*i) { sum += b.total; }
            }
        }
        sum
    }
}
