fn calc_flame_rows(rows: usize, app: &App) -> usize {
    if rows < 7 { return 0; }
    // header 3, footer 2 (border+help), panels*2
    let panels = if app.input_mode {
        1
    } else if app.info_msg.is_some() {
        // Selected + Info (+Debug?)
        if app.debug { 3 } else { 2 }
    } else if app.query.is_some() {
        // Match + Selected (+Debug?)
        if app.debug { 3 } else { 2 }
    } else {
        // Selected (+Debug?)
        if app.debug { 2 } else { 1 }
