        Err(e) => {
            // Adjust usage for long unknown args to match original: <FILENAME|--sorted|--echo|--debug>
            let mut s = e.to_string();
            // e.to_string() contains "Usage: <bin> ..." line. If error is unknown long arg and usage is not [OPTIONS], replace with group usage.
            // Detect: error contains "unexpected argument '--"
            if s.contains("unexpected argument '--") {
                // Check if usage is not already group and not [OPTIONS] alone? Actually for --unknown alone, usage is [OPTIONS], keep it.
                // For others, replace second line? Let's parse.
