                // We need to detect if usage contains "--sorted" or "<FILENAME>" (single) vs group.
                // If usage contains "--sorted" or "<FILENAME>" (without |), replace with group.
                // Simpler: if s contains "Usage:" and contains "--sorted" or "<FILENAME>" and not "<FILENAME|--sorted", then replace.
                if s.contains("--sorted") || s.contains("--echo") || s.contains("--debug") || s.contains("<FILENAME>") {
                    if !s.contains("<FILENAME|--sorted") {
                        // replace usage line
                        // Find bin name from s: after "Usage: "
                        if let Some(idx) = s.find("Usage: ") {
                            let after = &s[idx+7..];
